<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Edit, Key, Plus, Refresh, UserFilled, View } from '@element-plus/icons-vue'
import api from '../services/api'
import type { Account, Platform, User } from '../types'
import { dateTime, errorMessage, statusClass, statusText } from '../utils/format'
import PageHeader from '../components/PageHeader.vue'
import EmptyState from '../components/EmptyState.vue'

interface UsageRow{id:string;user_email:string;grant_id:string;task_id:string;event_type:string;details:Record<string,unknown>;created_at:string}
const loading=ref(true);const saving=ref(false);const error=ref('');const rows=ref<Account[]>([]);const platforms=ref<Platform[]>([]);const users=ref<User[]>([]);const q=ref('');const page=ref(1);const pageSize=ref(10)
const shown= computed(()=>rows.value.filter(a=>`${a.platform_name} ${a.label} ${a.account_hint}`.toLowerCase().includes(q.value.trim().toLowerCase())))
const pageRows=computed(()=>shown.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const credentialVisible=ref(false);const credentialMode=ref<'create'|'reauthorize'>('create');const credentialForm=reactive({platform_key:'',label:'',account_hint:'',auth_type:'',username:'',password:'',cookie_json:''});const currentAccount=ref<Account|null>(null)
const editVisible=ref(false);const editForm=reactive({label:'',is_open:false,status:'unchanged',available_from:'',expires_at:'',max_concurrency:1})
const grantVisible=ref(false);const grantSaving=ref(false);const grantForm=reactive({user_id:'',valid_from:'',expires_at:'',task_kinds:''})
const usageVisible=ref(false);const usageLoading=ref(false);const usage=ref<UsageRow[]>([]);const grantSearch=ref('')
const selectedPlatform=computed(()=>platforms.value.find(p=>p.key===credentialForm.platform_key))
const methods=computed(()=>selectedPlatform.value?.auth_methods.filter(x=>['username_password','cookies'].includes(x))||[])
const supported=computed(()=>['username_password','cookies'].includes(credentialForm.auth_type))
function activeGrants(account:Account){const now=Date.now();return (account.grants||[]).filter(g=>!g.revoked_at&&new Date(g.valid_from).getTime()<=now&&(!g.expires_at||new Date(g.expires_at).getTime()>now))}
const currentGrants=computed(()=>currentAccount.value?.grants||[])
const filteredGrants=computed(()=>currentGrants.value.filter(g=>`${g.user_email} ${g.user_id}`.toLowerCase().includes(grantSearch.value.trim().toLowerCase())))
function localIso(value:string){return value?new Date(value).toISOString():null}
function localInput(value?:string|null){if(!value)return '';const d=new Date(value);const pad=(x:number)=>String(x).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
async function load(){loading.value=true;error.value='';try{const [a,p,u]=await Promise.all([api.get<{shared_accounts:Account[]}>('/admin/shared-accounts'),api.get<{platforms:Platform[]}>('/platforms'),api.get<{users:User[]}>('/admin/users?page=1&page_size=100')]);rows.value=a.data.shared_accounts;platforms.value=p.data.platforms;users.value=u.data.users.filter(x=>x.status==='active'&&x.roles.includes('user')&&!x.roles.includes('admin')&&!x.roles.includes('superadmin'))}catch(err){error.value=errorMessage(err)}finally{loading.value=false}}
function resetCredential(){const key=platforms.value[0]?.key||'';const p=platforms.value.find(x=>x.key===key);Object.assign(credentialForm,{platform_key:key,label:'',account_hint:'',auth_type:p?.auth_methods.find(m=>['username_password','cookies'].includes(m))||'',username:'',password:'',cookie_json:''})}
function changePlatform(key:string){credentialForm.auth_type=platforms.value.find(p=>p.key===key)?.auth_methods.find(m=>['username_password','cookies'].includes(m))||'';credentialForm.username='';credentialForm.password='';credentialForm.cookie_json=''}
function openCreate(){credentialMode.value='create';currentAccount.value=null;resetCredential();credentialVisible.value=true}
function openReauthorize(row:Account){currentAccount.value=row;credentialMode.value='reauthorize';credentialForm.platform_key=row.platform_key;credentialForm.label=row.label;credentialForm.account_hint='';credentialForm.auth_type=platforms.value.find(p=>p.key===row.platform_key)?.auth_methods.find(m=>['username_password','cookies'].includes(m))||'';credentialForm.username='';credentialForm.password='';credentialForm.cookie_json='';credentialVisible.value=true}
function credentials(){if(credentialForm.auth_type==='username_password')return credentialForm.username.trim()&&credentialForm.password?{username:credentialForm.username.trim(),password:credentialForm.password}:null;if(credentialForm.auth_type==='cookies'){try{const parsed=JSON.parse(credentialForm.cookie_json);return parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:null}catch{return null}}return null}
async function submitCredentials(){const credential=credentials();if(!credential){ElMessage.warning(credentialForm.auth_type==='cookies'?'请输入有效的 Cookie JSON。':'请输入平台用户名和密码。');return}if(credentialMode.value==='create'&&!credentialForm.account_hint.trim()){ElMessage.warning('请填写账号标识；服务端会自动脱敏。');return}saving.value=true;try{if(credentialMode.value==='create'){await api.post('/admin/shared-accounts',{platform_key:credentialForm.platform_key,label:credentialForm.label.trim(),account_hint:credentialForm.account_hint.trim(),auth_type:credentialForm.auth_type,credentials:credential,is_open:false,max_concurrency:1});ElMessage.success('共享账号已加密保存，状态仍为未验证。')}else if(currentAccount.value){await api.post(`/admin/shared-accounts/${currentAccount.value.id}/reauthorize`,{auth_type:credentialForm.auth_type,credentials:credential});ElMessage.success('新凭证已加密提交；平台验证通过前账号仍不可执行。')}credentialVisible.value=false;credentialForm.password='';credentialForm.cookie_json='';await load()}catch(err){ElMessage.error(errorMessage(err))}finally{saving.value=false}}
function openEdit(row:Account){currentAccount.value=row;Object.assign(editForm,{label:row.label||'',is_open:!!row.is_open,status:'unchanged',available_from:localInput(row.available_from),expires_at:localInput(row.expires_at),max_concurrency:row.max_concurrency||1});editVisible.value=true}
async function saveMetadata(){if(!currentAccount.value)return;if(editForm.expires_at&&editForm.available_from&&new Date(editForm.expires_at)<=new Date(editForm.available_from)){ElMessage.warning('账号截止时间必须晚于开始时间。');return}if(currentAccount.value.is_open&&(!editForm.is_open||editForm.status==='disabled')){try{await ElMessageBox.confirm('关闭或禁用共享账号会阻止新任务，并请求取消正在运行的任务。','确认关闭共享访问',{type:'warning'})}catch{return}}saving.value=true;try{const payload:any={label:editForm.label.trim(),is_open:editForm.is_open,available_from:localIso(editForm.available_from),expires_at:localIso(editForm.expires_at),max_concurrency:editForm.max_concurrency};if(editForm.status!=='unchanged')payload.status=editForm.status;await api.patch(`/admin/shared-accounts/${currentAccount.value.id}`,payload);ElMessage.success('共享账号设置已更新');editVisible.value=false;await load()}catch(err){ElMessage.error(errorMessage(err))}finally{saving.value=false}}
function openGrant(row:Account){currentAccount.value=row;Object.assign(grantForm,{user_id:'',valid_from:'',expires_at:'',task_kinds:''});grantSearch.value='';grantVisible.value=true}
async function grantAccess(){if(!currentAccount.value||!grantForm.user_id){ElMessage.warning('请选择要授权的普通用户。');return}if(grantForm.expires_at&&grantForm.valid_from&&new Date(grantForm.expires_at)<=new Date(grantForm.valid_from)){ElMessage.warning('授权截止时间必须晚于开始时间。');return}grantSaving.value=true;try{const taskKinds=grantForm.task_kinds.split(',').map(x=>x.trim()).filter(Boolean);await api.post(`/admin/shared-accounts/${currentAccount.value.id}/grants`,{user_id:grantForm.user_id,valid_from:localIso(grantForm.valid_from),expires_at:localIso(grantForm.expires_at),scope:taskKinds.length?{task_kinds:taskKinds}:{}});ElMessage.success('共享账号授权已创建');await load();const refreshed=rows.value.find(x=>x.id===currentAccount.value?.id);if(refreshed)currentAccount.value=refreshed;grantForm.user_id=''}catch(err){ElMessage.error(errorMessage(err))}finally{grantSaving.value=false}}
async function revokeGrant(grant:any){try{await ElMessageBox.confirm(`撤销 ${grant.user_email} 的共享账号授权？运行任务会收到取消请求，账号槽需等待 Worker 确认或租约过期。`,'撤销共享授权',{type:'warning',confirmButtonText:'确认撤销',cancelButtonText:'取消'});await api.post(`/admin/shared-accounts/${currentAccount.value?.id}/grants/${grant.id}/revoke`,{});ElMessage.success('授权已撤销');await load();currentAccount.value=rows.value.find(x=>x.id===currentAccount.value?.id)||null}catch(err:any){if(err!=='cancel'&&err!=='close')ElMessage.error(errorMessage(err))}}
async function showUsage(row:Account){currentAccount.value=row;usageVisible.value=true;usageLoading.value=true;try{const {data}=await api.get<{usage_logs:UsageRow[]}>(`/admin/shared-accounts/${row.id}/usage`);usage.value=data.usage_logs}catch(err){ElMessage.error(errorMessage(err))}finally{usageLoading.value=false}}
async function toggleOpen(row:Account,value:boolean|string|number){const open=Boolean(value);if(!open){try{await ElMessageBox.confirm('关闭共享会阻止新任务，并请求取消运行中的任务。','关闭共享账号',{type:'warning'})}catch{await load();return}}try{await api.patch(`/admin/shared-accounts/${row.id}`,{is_open:open});ElMessage.success(open?'已开放共享':'已关闭共享');await load()}catch(err){ElMessage.error(errorMessage(err));await load()}}
onMounted(load)
</script>

<template>
  <div class="page-wrap">
    <PageHeader eyebrow="SHARED ACCESS ADMIN" title="共享账号管理" description="管理员可维护自己创建的共享账号和授权。密文不提供回显；平台验证尚未接入时，开放账号仍会显示为不可执行。"><el-button type="primary" :icon="Plus" @click="openCreate">新建共享账号</el-button></PageHeader>
    <div class="notice-strip warning shared-admin-notice">危险操作会二次确认。关闭共享、禁用账号或撤销授权会阻止新任务，并请求取消已运行任务。</div>
    <section class="surface surface-pad">
      <div class="table-toolbar"><el-input v-model="q" class="table-search" clearable placeholder="搜索平台、备注或脱敏标识" @input="page=1"><template #prefix><el-icon><Key /></el-icon></template></el-input><span class="muted text-small">{{ rows.length }} 个由你管理的共享账号</span></div>
      <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" />
      <el-table v-loading="loading" :data="pageRows" class="data-table" row-key="id">
        <el-table-column label="平台 / 账号" min-width="190"><template #default="{row}"><div class="table-primary">{{ row.platform_name }}</div><div class="table-secondary">{{ row.account_hint }}</div></template></el-table-column>
        <el-table-column label="备注" min-width="130"><template #default="{row}">{{ row.label||'未设置' }}</template></el-table-column>
        <el-table-column label="验证状态" width="120"><template #default="{row}"><span class="status-pill" :class="statusClass(row.status)">{{ statusText(row.status) }}</span></template></el-table-column>
        <el-table-column label="共享状态" width="120"><template #default="{row}"><el-switch :model-value="row.is_open" inline-prompt active-text="开放" inactive-text="关闭" @change="toggleOpen(row, $event)" /></template></el-table-column>
        <el-table-column label="授权用户" min-width="105"><template #default="{row}">{{ activeGrants(row).length }} 个有效授权</template></el-table-column>
        <el-table-column label="账号有效期" min-width="145"><template #default="{row}">{{ row.expires_at?dateTime(row.expires_at):'长期有效' }}</template></el-table-column>
        <el-table-column label="操作" fixed="right" min-width="270"><template #default="{row}"><div class="table-actions"><el-button link type="primary" @click="openEdit(row)"><el-icon><Edit /></el-icon>设置</el-button><el-button link type="primary" @click="openGrant(row)"><el-icon><UserFilled /></el-icon>授权</el-button><el-button link type="primary" @click="openReauthorize(row)">重新授权</el-button><el-button link type="primary" @click="showUsage(row)"><el-icon><View /></el-icon>使用记录</el-button></div></template></el-table-column>
        <template #empty><EmptyState title="还没有共享账号" description="创建账号后可以设为开放并授予指定普通用户；授权记录会由后端保留。" /></template>
      </el-table>
      <div class="pagination-row"><span>共 {{ shown.length }} 项</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="shown.length" :page-sizes="[10,20,50]" layout="sizes, prev, pager, next" /></div>
    </section>

    <el-dialog v-model="credentialVisible" :title="credentialMode==='create'?'创建共享账号':'重新提交共享账号凭证'" width="560px" destroy-on-close>
      <div class="secret-note">密文仅在服务端加密保存且不会回显。账号新建或重新授权后均回到“未验证”；请勿在前端填入新系统不应复用的旧 AI Key。</div>
      <el-form label-position="top"><div v-if="credentialMode==='create'" class="form-grid"><el-form-item label="平台" required><el-select v-model="credentialForm.platform_key" style="width:100%" @change="changePlatform"><el-option v-for="p in platforms" :key="p.key" :label="p.name" :value="p.key"/></el-select></el-form-item><el-form-item label="备注"><el-input v-model="credentialForm.label" maxlength="120"/></el-form-item><el-form-item label="账号标识" class="full" required><el-input v-model="credentialForm.account_hint" maxlength="120" placeholder="输入账号或邮箱；服务端会自动脱敏"/><div class="form-hint">列表中只显示脱敏标识；共享用户不会看到凭证。</div></el-form-item></div><el-form-item label="授权方式" required><el-select v-model="credentialForm.auth_type" style="width:100%"><el-option v-for="method in methods" :key="method" :value="method" :label="method==='username_password'?'账号密码':method==='cookies'?'Cookie 凭证':method"/></el-select><div v-if="!methods.length" class="form-hint">此平台没有可通过当前表单提交的授权方式，不能模拟二维码登录。</div></el-form-item><div v-if="credentialForm.auth_type==='username_password'" class="form-grid"><el-form-item label="平台用户名" required><el-input v-model="credentialForm.username" autocomplete="off"/></el-form-item><el-form-item label="平台密码" required><el-input v-model="credentialForm.password" type="password" show-password autocomplete="new-password"/></el-form-item></div><el-form-item v-else-if="credentialForm.auth_type==='cookies'" label="Cookie JSON" required><el-input v-model="credentialForm.cookie_json" type="textarea" :rows="5" placeholder='{"cookies":"..."}' autocomplete="off"/></el-form-item></el-form>
      <template #footer><el-button @click="credentialVisible=false">取消</el-button><el-button type="primary" :disabled="!supported" :loading="saving" @click="submitCredentials">加密提交</el-button></template>
    </el-dialog>
    <el-dialog v-model="editVisible" title="共享账号设置" width="520px"><el-form label-position="top"><div class="form-grid"><el-form-item label="账号备注" class="full"><el-input v-model="editForm.label" maxlength="120"/></el-form-item><el-form-item label="共享开放"><el-switch v-model="editForm.is_open" inline-prompt active-text="开放" inactive-text="关闭"/></el-form-item><el-form-item label="验证状态"><el-select v-model="editForm.status" style="width:100%"><el-option label="保持现状" value="unchanged"/><el-option label="重置为未验证" value="unverified"/><el-option label="禁用账号" value="disabled"/></el-select><div class="form-hint">不能手工将账号设为已验证/active。</div></el-form-item><el-form-item label="开放起始时间"><el-date-picker v-model="editForm.available_from" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="立即" style="width:100%"/></el-form-item><el-form-item label="账号截止时间"><el-date-picker v-model="editForm.expires_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="不设截止" style="width:100%"/></el-form-item><el-form-item label="并发上限" class="full"><el-input-number v-model="editForm.max_concurrency" :min="1" :max="16"/><div class="form-hint">平台没有经过验证的并行会话能力时，后端仍会把有效并发限制为 1。</div></el-form-item></div></el-form><template #footer><el-button @click="editVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveMetadata">保存设置</el-button></template></el-dialog>
    <el-drawer v-model="grantVisible" :title="`共享授权 · ${currentAccount?.label||currentAccount?.platform_name||''}`" size="min(760px, 96vw)"><div class="grant-drawer"><div class="notice-strip warning">只可以授予当前管理范围内的普通用户。授权到期或撤销后，账号会从该用户的列表中消失。</div><div class="grant-form"><el-select v-model="grantForm.user_id" filterable placeholder="选择普通用户"><el-option v-for="user in users" :key="user.id" :label="`${user.display_name||user.email} · ${user.email}`" :value="user.id"/></el-select><el-date-picker v-model="grantForm.valid_from" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="授权开始（默认立即）"/><el-date-picker v-model="grantForm.expires_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" placeholder="有效期截止（可选）"/><el-input v-model="grantForm.task_kinds" placeholder="任务范围，逗号分隔；留空不限制"><template #prefix>范围</template></el-input><el-button type="primary" :loading="grantSaving" @click="grantAccess">授予账号</el-button></div><div class="grant-list-head"><div><h3>授权历史</h3><p>包含当前、已撤销和过期记录。</p></div><el-input v-model="grantSearch" clearable placeholder="筛选用户" style="width:180px"/></div><el-table :data="filteredGrants" class="data-table"><el-table-column label="用户" min-width="180"><template #default="{row}"><div class="table-primary">{{ row.user_email }}</div><div class="table-secondary">{{ row.user_id.slice(0,8) }}…</div></template></el-table-column><el-table-column label="有效期" min-width="175"><template #default="{row}">{{ dateTime(row.valid_from) }}<div class="table-secondary">至 {{ row.expires_at?dateTime(row.expires_at):'未设截止' }}</div></template></el-table-column><el-table-column label="范围" min-width="130"><template #default="{row}">{{ row.scope?.task_kinds?.length?row.scope.task_kinds.join('、'):'不限制任务类型' }}</template></el-table-column><el-table-column label="授权状态" min-width="110"><template #default="{row}"><span class="status-pill" :class="row.revoked_at?'status-off':row.expires_at&&new Date(row.expires_at).getTime()<Date.now()?'status-off':'status-ok'">{{ row.revoked_at?'已撤销':row.expires_at&&new Date(row.expires_at).getTime()<Date.now()?'已过期':'有效/待生效' }}</span></template></el-table-column><el-table-column label="操作" width="80"><template #default="{row}"><el-button v-if="!row.revoked_at&&(!row.expires_at||new Date(row.expires_at).getTime()>Date.now())" link type="danger" @click="revokeGrant(row)">撤销</el-button></template></el-table-column><template #empty><EmptyState title="还没有授权记录" description="使用上方表单为普通用户授予共享账号访问权。"/></template></el-table></div></el-drawer>
    <el-dialog v-model="usageVisible" :title="`使用记录 · ${currentAccount?.label||currentAccount?.platform_name||''}`" width="760px"><div class="notice-strip">使用记录只显示平台侧授权/任务事件元数据，凭证内容不会记录在日志中。</div><el-table v-loading="usageLoading" :data="usage" class="data-table usage-table"><el-table-column label="用户" prop="user_email" min-width="170"/><el-table-column label="事件" prop="event_type" min-width="140"/><el-table-column label="任务" min-width="110"><template #default="{row}">{{ row.task_id.slice(0,8) }}…</template></el-table-column><el-table-column label="时间" min-width="155"><template #default="{row}">{{ dateTime(row.created_at) }}</template></el-table-column><template #empty><EmptyState title="暂无使用记录" description="账号产生共享授权或任务事件后会显示在此。"/></template></el-table></el-dialog>
  </div>
</template>

<style scoped>.shared-admin-notice{margin:-3px 0 15px}.grant-form{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:15px;margin:14px 0 20px;background:#f7faf9;border:1px solid #e9f0ee;border-radius:11px}.grant-form .el-button{grid-column:1/-1}.grant-list-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:13px 0}.grant-list-head h3{margin:0;color:#415763;font-size:12px}.grant-list-head p{margin:4px 0 0;color:#919da3;font-size:9px}.grant-drawer{display:grid;gap:8px}.usage-table{margin-top:12px}@media(max-width:680px){.grant-form{grid-template-columns:1fr}.grant-form .el-button{grid-column:auto}}</style>
